// bootstrapPrimaryFromCheckpointRemote tries to populate a missing local primary
// metadata ref from a configured checkpoint_remote before the caller falls back
// to creating an empty orphan. When a separate checkpoint_remote already holds
// the real entire/checkpoints/v1 branch (the common second-device case), a fresh
// local orphan would diverge from it — hiding existing checkpoints and causing
// non-fast-forward rejections on the next fetch.
//
// All resolution is pinned to repo's worktree (settings, origin URL, fetch
// working directory, ref promotion) so the decision depends on the repository
// being ensured rather than the ambient working directory.
//
// It returns true only when the fetch succeeds and the local primary ref now
// points at the remote branch. Every failure is non-fatal and returns false so
// the caller creates the empty orphan: `entire enable` must never break on a
// missing checkpoint remote, an unresolvable URL, or a network/auth error.
func bootstrapPrimaryFromCheckpointRemote(ctx context.Context, repo *git.Repository, primary plumbing.ReferenceName) bool {
	if !checkpointRemoteBootstrapAllowed(ctx) {
		// Not an explicit setup flow (e.g. the per-turn hook hot path via
		// EnsureSetup). Never fetch here: hook execution has a hard timeout,
		// and a slow/unreachable checkpoint remote must not stall every turn.
		// Fall back to the empty orphan, which self-heals immediately.
		logging.Debug(ctx, "checkpoint-remote: skipping bootstrap fetch outside explicit enable flow")
		return false
	}

	worktreeRoot, err := getRepoPath(repo)
	if err != nil {
		logging.Debug(ctx, "checkpoint-remote: cannot resolve worktree root for enable bootstrap",
			slog.String("error", err.Error()),
		)
		return false
	}
	// Pin settings/remote resolution to this repo's worktree.
	ctx = settings.WithWorktreeRoot(ctx, worktreeRoot)

	// Resolve and verify the checkpoint fetch URL. resolveCheckpointFetchURL
	// rejects remote.FetchURL's silent origin fallback, so bootstrap never adopts
	// origin's data when the derived URL doesn't actually target the configured
	// checkpoint repo (issue #1374).
	url, ok := resolveCheckpointFetchURL(ctx, worktreeRoot)
	if !ok {
		return false
	}

	branchName := primary.Short()
	tmpRefName := plumbing.ReferenceName(FetchTmpRefPrefix + branchName)
	if err := fetchURLIntoTmpRef(ctx, worktreeRoot, url, primary.String(), tmpRefName.String(), "metadata branch", true); err != nil {
		logging.Debug(ctx, "checkpoint-remote: enable bootstrap fetch failed; creating empty orphan",
			slog.String("url", remote.RedactURL(url)),
			slog.String("error", err.Error()),
		)
		return false
	}
	defer func() { _ = repo.Storer.RemoveReference(tmpRefName) }() //nolint:errcheck // cleanup is best-effort

	tmpRef, err := repo.Reference(tmpRefName, true)
	if err != nil {
		logging.Debug(ctx, "checkpoint-remote: fetched metadata ref missing after enable bootstrap",
			slog.String("error", err.Error()),
		)
		return false
	}
	if err := SafelyAdvanceLocalRef(ctx, repo, primary, tmpRef.Hash()); err != nil {
		logging.Debug(ctx, "checkpoint-remote: could not advance local metadata ref on enable bootstrap",
			slog.String("error", err.Error()),
		)
		return false
	}
	logging.Info(ctx, "checkpoint-remote: bootstrapped metadata branch on enable",
		slog.String("ref", primary.String()),
	)
	return true
}

// healPrimaryFromCheckpointRemote replaces a local primary metadata ref that holds
// no checkpoint data — an empty orphan, or a vercel.json-only orphan on a
// vercel-enabled repo — with the real branch fetched from a configured
// checkpoint_remote. It repairs second-device repos left with an un-initialized
// orphan disjoint from the remote history (issue #1374).
//
// The network fetch is gated on an explicit enable flow
// (WithCheckpointRemoteBootstrap); the per-turn hook hot path stays network-free.
// Returns true only when the local ref was replaced with real remote data. A
// local branch that already carries checkpoints, a non-enable context, an
// unresolvable URL, or a fetch that yields no usable data all return (false, nil)
// so the caller keeps the local ref as-is.
func healPrimaryFromCheckpointRemote(ctx context.Context, repo *git.Repository, localRef *plumbing.Reference, primary plumbing.ReferenceName) (bool, error) {
	hasData, err := metadataBranchHasData(repo, localRef)
	if err != nil {
		return false, fmt.Errorf("failed to check metadata branch contents: %w", err)
	}
	if hasData {
		return false, nil
	}
	if !checkpointRemoteBootstrapAllowed(ctx) {
		// Not an explicit setup flow (e.g. the per-turn hook hot path). Never
		// fetch here: the local orphan self-heals on the next explicit enable.
		logging.Debug(ctx, "checkpoint-remote: skipping empty-orphan heal outside explicit enable flow")
		return false, nil
	}
	return healEmptyOrphanFromCheckpointRemote(ctx, repo, primary)
}

// FetchMetadataBranch fetches the metadata branch from the checkpoint remote URL
// and updates the local branch. Unlike fetchMetadataBranchIfMissing, this always
// fetches regardless of whether the branch exists locally (for resume scenarios
// where the local branch may be stale).
//
// The fetch is unfiltered (NoFilter: true) because resume needs blob content
// (transcripts, metadata JSON) — not just tree objects.
func FetchMetadataBranch(ctx context.Context, remoteURL string) error {
	refs := checkpoint.ResolveRefs(ctx)
	if !refs.Primary.IsBranch() {
		return fmt.Errorf("primary metadata ref %s is not a branch", refs.Primary)
	}
	branchName := refs.Primary.Short()
	tmpRef := FetchTmpRefPrefix + branchName
	srcRef := refs.Primary.String()

	if err := fetchURLIntoTmpRef(ctx, "", remoteURL, srcRef, tmpRef, "metadata branch", true); err != nil {
		return err
	}
	if err := PromoteTmpRefSafely(ctx, plumbing.ReferenceName(tmpRef), refs.Primary, branchName); err != nil {
		return err
	}

	return nil
}

// fetchURLIntoTmpRef runs `git fetch <remoteURL> +<srcRef>:<tmpRef>` via the
// checkpoint git wrapper, disabling the terminal prompt so a misconfigured
// credential helper doesn't hang the process. Errors include the redacted URL
// and any captured stderr so operators can diagnose without credentials
// leaking into logs.
//
// When noFilter is true, --filter=blob:none is suppressed even if filtered
// fetches are globally enabled. Use noFilter for operations that need blob
// content (resume, explain) as opposed to sync operations (push recovery)
// that only need tree structure.
func fetchURLIntoTmpRef(ctx context.Context, dir, remoteURL, srcRef, tmpRef, label string, noFilter bool) error { //nolint:unparam // noFilter distinguishes blob-content fetches (true) from tree-only sync fetches (false); kept for the documented fetch-filtering contract even though current callers all need blob content
	fetchCtx, cancel := context.WithTimeout(ctx, checkpointRemoteFetchTimeout)
	defer cancel()

	refSpec := fmt.Sprintf("+%s:%s", srcRef, tmpRef)
	output, fetchErr := remote.Fetch(fetchCtx, remote.FetchOptions{
		Remote:   remoteURL,
		RefSpecs: []string{refSpec},
		NoTags:   true,
		NoFilter: noFilter,
		Dir:      dir,
	})
	if fetchErr == nil {
		return nil
	}

	redactedURL := remote.RedactURL(remoteURL)
	msg := strings.TrimSpace(strings.ReplaceAll(string(output), remoteURL, redactedURL))
	if msg != "" {
		return fmt.Errorf("fetch %s from %s failed: %s: %w", label, redactedURL, msg, fetchErr)
	}
	return fmt.Errorf("fetch %s from %s failed: %w", label, redactedURL, fetchErr)
}

// fetchMetadataBranchIfMissing fetches the primary metadata ref from a URL only if it doesn't exist locally.
// This avoids network calls on every push — once the branch exists locally, this is a no-op.
// Fetch failures are silently swallowed (returns nil): the push will handle creating the
// branch on the remote. Only fatal errors (opening repo, creating local branch) are returned.
func fetchMetadataBranchIfMissing(ctx context.Context, remoteURL string) error {
	repo, err := OpenRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}
	defer repo.Close()

	// Check if branch already exists locally - if so, nothing to do
	refs := checkpoint.ResolveRefs(ctx)
	if _, err := repo.Reference(refs.Primary, true); err == nil {
		return nil // Branch exists locally, skip fetch
	}

	// Branch doesn't exist locally - try to fetch it from the URL.
	// Fetch failures are not fatal: push will create it on the remote when it succeeds.
	if err := FetchMetadataBranch(ctx, remoteURL); err != nil {
		return nil
	}

	logging.Info(ctx, "checkpoint-remote: fetched metadata branch from URL")
	return nil
}

// resolveCheckpointFetchURL resolves the checkpoint_remote fetch URL for the repo
// rooted at worktreeRoot and verifies it actually targets the configured
// checkpoint repository. It returns ok=false (never an error) when no
// checkpoint_remote is configured or a dedicated checkpoint URL cannot be
// resolved, so callers fall back to keeping the local branch / creating an orphan.
//
// remote.FetchURL silently falls back to the origin remote URL in several paths
// (ENTIRE_CHECKPOINT_TOKEN short-circuit, unparseable origin, non-derivable origin
// protocol). Adopting from origin would contradict the rule that origin is never
// authoritative when a checkpoint_remote is configured (issue #1374), so a resolved
// URL that does not target the configured checkpoint repo is treated as unresolved.
func resolveCheckpointFetchURL(ctx context.Context, worktreeRoot string) (string, bool) {
	s, err := settings.Load(ctx)
	if err != nil {
		logging.Debug(ctx, "checkpoint-remote: could not load settings for metadata fetch URL",
			slog.String("error", err.Error()))
		return "", false
	}
	config := s.GetCheckpointRemote()
	if config == nil {
		return "", false
	}
	url, err := remote.FetchURL(ctx, remote.FetchURLOptions{WorktreeRoot: worktreeRoot})
	if err != nil || strings.TrimSpace(url) == "" {
		logging.Debug(ctx, "checkpoint-remote: could not resolve fetch URL for metadata bootstrap",
			slog.Any("error", err))
		return "", false
	}
	if !urlTargetsCheckpointRepo(url, config) {
		logging.Debug(ctx, "checkpoint-remote: fetch URL did not resolve to the configured checkpoint repo; not adopting from origin",
			slog.String("repo", config.Repo))
		return "", false
	}
	return url, true
}

// urlTargetsCheckpointRepo reports whether url points at the configured checkpoint
// repository (host-agnostic, case-insensitive owner/repo match). It distinguishes a
// derived checkpoint URL from remote.FetchURL's origin fallback, which targets the
// origin repository instead. A same-repo checkpoint_remote (origin == checkpoint
// repo) still matches, which is correct: adopting from that URL is adopting the
// checkpoint repo.
func urlTargetsCheckpointRepo(url string, config *settings.CheckpointRemoteConfig) bool {
	info, err := remote.ParseURL(url)
	if err != nil || info.Owner == "" || info.Repo == "" {
		return false
	}
	return strings.EqualFold(info.Owner+"/"+info.Repo, config.Repo)
}

